package caddycmd

import "testing"

func TestTmpIssueScenario(t *testing.T) {
	cases := []struct {
		configFile  string
		adapterName string
		want        bool
		wantErr     bool
	}{
		{".serve/Caddyfile.preview", "", true, false},
		{".serve/Caddyfile.prd", "", true, false},
		{".serve/Caddyfile", "", true, false},
		{"/home/user/.serve/Caddyfile.preview", "", true, false},
		{"Caddyfile.yaml", "", false, true},
	}
	for _, tc := range cases {
		got, err := isCaddyfile(tc.configFile, tc.adapterName)
		if (err != nil) != tc.wantErr {
			t.Errorf("%q adapter=%q: err=%v, wantErr=%v", tc.configFile, tc.adapterName, err, tc.wantErr)
			continue
		}
		if got != tc.want {
			t.Errorf("%q adapter=%q: got=%v, want=%v", tc.configFile, tc.adapterName, got, tc.want)
		}
	}
}
